"""FRR configs for the five routers: eBGP on every link, ROV on the transits, forged origin on origin2."""

from __future__ import annotations

from pathlib import Path

from .topology import NODES, OWN_PREFIXES, RTR_PORT, neighbours, router_id

DAEMONS = """\
# generated by lab/render/frr.py
bgpd=yes
zebra_options="  -A 127.0.0.1 -s 90000000"
bgpd_options="   -A 127.0.0.1 -M rpki"
staticd_options="-A 127.0.0.1"
mgmtd_options="  -A 127.0.0.1"
vtysh_enable=yes
"""

VTYSH = "service integrated-vtysh-config\n"


def _header(node: str) -> list[str]:
    return ["! generated by lab/render/frr.py", "frr defaults traditional", f"hostname {node}", "log stdout", "!"]


def _bgp(node: str, networks: list[str], rm_in: str | None, rm_out: str | None) -> list[str]:
    asn = NODES[node].asn
    peers = neighbours(node)
    out = [f"router bgp {asn}", f" bgp router-id {router_id(node)}", " no bgp ebgp-requires-policy"]
    out += [f" neighbor {ip} remote-as {pasn}" for ip, pasn, _ in peers]
    out += [f" neighbor {ip} description {name}" for ip, _, name in peers]
    out.append(" address-family ipv4 unicast")
    out += [f"  network {p}" for p in networks]
    for ip, _, _ in peers:
        if rm_in:
            out.append(f"  neighbor {ip} route-map {rm_in} in")
        if rm_out:
            out.append(f"  neighbor {ip} route-map {rm_out} out")
    out += [" exit-address-family", "exit", "!"]
    return out


def render_router(node: str, sc: dict) -> str:
    role_asn = NODES[node].asn
    lines = _header(node)
    networks = list(OWN_PREFIXES[node])
    rm_in = rm_out = None
    if node == "origin":
        networks.insert(0, sc["victim"]["prefix"])
    elif node == "origin2":
        ms = sc["attacker"]["more_specifics"]
        networks += [ms[k] for k in sc["attacker"]["announce"]]
        rm_out = "FORGE"
        lines += [
            f"ip prefix-list ATTACK seq 5 permit {ms['web']}",
            f"ip prefix-list ATTACK seq 10 permit {ms['ns']}",
            "!",
            "route-map FORGE permit 10",
            " match ip address prefix-list ATTACK",
            f" set as-path prepend {sc['victim']['asn']}",  # forged origin: the path ends in the victim's AS
            "exit",
            "route-map FORGE permit 20",
            "exit",
            "!",
        ]
    elif role_asn in sc["transits"]:
        if sc["rov"]:
            rm_in = "ROV"
            lines += [
                "rpki",
                f" rpki cache tcp {NODES['rpki'].mgmt} {RTR_PORT} preference 1",
                " rpki retry_interval 5",
                " rpki polling_period 30",
                "exit",
                "!",
                "route-map ROV deny 10",
                " match rpki invalid",
                "exit",
                "route-map ROV permit 20",
                "exit",
                "!",
            ]
    elif node == "collector":
        rm_out = "COLLECTOR-OUT"  # listen-only: exports nothing but its own CA link
        lines += [
            f"ip prefix-list OWN seq 5 permit {OWN_PREFIXES['collector'][0]}",
            "!",
            "route-map COLLECTOR-OUT permit 10",
            " match ip address prefix-list OWN",
            "exit",
            "!",
        ]
    lines += _bgp(node, networks, rm_in, rm_out)
    return "\n".join(lines) + "\n"


def render_frr(sc: dict, build: Path) -> None:
    for node, n in NODES.items():
        if n.role != "router":
            continue
        d = build / node
        d.mkdir(parents=True, exist_ok=True)
        (d / "frr.conf").write_text(render_router(node, sc))
        (d / "daemons").write_text(DAEMONS)
        (d / "vtysh.conf").write_text(VTYSH)
